from pathlib import Path
import sys

root=Path(sys.argv[1] if len(sys.argv)>1 else "gawone-management-pilot")

# Version
p=root/"app/build.gradle.kts"
s=p.read_text()
s=s.replace('versionCode = 3','versionCode = 4',1)
s=s.replace('versionName = "0.2.1-pilot-m1.1"','versionName = "0.2.2-pilot-m1.2"',1)
p.write_text(s)

# Manifest: private cache FileProvider
p=root/"app/src/main/AndroidManifest.xml"
s=p.read_text()
anchor='''        <activity android:name=".MainActivity" android:exported="true">'''
provider='''        <provider\n            android:name="androidx.core.content.FileProvider"\n            android:authorities="${applicationId}.fileprovider"\n            android:exported="false"\n            android:grantUriPermissions="true">\n            <meta-data\n                android:name="android.support.FILE_PROVIDER_PATHS"\n                android:resource="@xml/file_paths" />\n        </provider>\n        <activity android:name=".MainActivity" android:exported="true">'''
if anchor not in s: raise SystemExit("manifest anchor missing")
s=s.replace(anchor,provider,1)
p.write_text(s)

xml=root/"app/src/main/res/xml"
xml.mkdir(parents=True,exist_ok=True)
(xml/"file_paths.xml").write_text('''<?xml version="1.0" encoding="utf-8"?>\n<paths xmlns:android="http://schemas.android.com/apk/res/android">\n    <cache-path name="kyc_review_cache" path="kyc-review/" />\n</paths>\n''')

# API: authenticated private Storage download, no public/signed URL and no privileged key
p=root/"app/src/main/java/site/garsyanimultiusaha/gawone/management/ManagementApi.kt"
s=p.read_text()
s=s.replace('import java.net.URLEncoder\n','import java.net.URLEncoder\nimport java.io.File\n')
s=s.replace('''class ManagementApi(context: Context) {\n    private val store=SessionStore(context.applicationContext)''','''class ManagementApi(context: Context) {\n    private val appContext=context.applicationContext\n    private val store=SessionStore(appContext)''')
s=s.replace('''    fun hasSession()=store.load()!=null\n    fun logout()=store.clear()''','''    fun hasSession()=store.load()!=null\n    fun logout(){\n        File(appContext.cacheDir,"kyc-review").deleteRecursively()\n        store.clear()\n    }''')
anchor='''    fun userId():String? {'''
method='''    suspend fun downloadStorage(bucket:String,path:String):ByteArray=withContext(Dispatchers.IO){\n        require(bucket.isNotBlank() && path.isNotBlank()){ "Storage path kosong" }\n        try { downloadStorageOnce(bucket,path) } catch(e:ApiException){\n            if(e.status==401 && refresh()) downloadStorageOnce(bucket,path) else throw e\n        }\n    }\n    private fun downloadStorageOnce(bucket:String,path:String):ByteArray {\n        val token=store.load()?.accessToken?:throw ApiException(401,"Sesi berakhir")\n        val encPath=path.split('/').joinToString("/"){ URLEncoder.encode(it,"UTF-8").replace("+","%20") }\n        val encBucket=URLEncoder.encode(bucket,"UTF-8").replace("+","%20")\n        val c=(URL("$base/storage/v1/object/authenticated/$encBucket/$encPath").openConnection() as HttpURLConnection)\n        c.requestMethod="GET"\n        c.connectTimeout=15000\n        c.readTimeout=30000\n        c.setRequestProperty("apikey",key)\n        c.setRequestProperty("Authorization","Bearer $token")\n        val code=c.responseCode\n        if(code !in 200..299){\n            val text=c.errorStream?.bufferedReader()?.use{it.readText()}.orEmpty()\n            throw ApiException(code,extractError(text))\n        }\n        if(c.contentLengthLong > 12L*1024L*1024L) throw ApiException(413,"Bukti KYC terlalu besar untuk preview")\n        val bytes=c.inputStream.use{it.readBytes()}\n        if(bytes.size > 12*1024*1024) throw ApiException(413,"Bukti KYC terlalu besar untuk preview")\n        return bytes\n    }\n\n'''
if anchor not in s: raise SystemExit("api anchor missing")
s=s.replace(anchor,method+anchor,1)
p.write_text(s)

# UI: storage_path + secure screen + reviewer evidence preview
p=root/"app/src/main/java/site/garsyanimultiusaha/gawone/management/MainActivity.kt"
s=p.read_text()
s=s.replace('import android.os.Bundle\n','import android.os.Bundle\nimport android.content.Intent\nimport android.view.WindowManager\n')
s=s.replace('import androidx.compose.ui.Modifier\n','import androidx.compose.ui.Modifier\nimport androidx.compose.ui.platform.LocalContext\n')
s=s.replace('import kotlinx.coroutines.launch\n','import kotlinx.coroutines.launch\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\n')
s=s.replace('import org.json.JSONObject\n','import org.json.JSONObject\nimport androidx.core.content.FileProvider\nimport java.io.File\n')
s=s.replace('''class MainActivity:ComponentActivity(){\n    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{ManagementApp(ManagementApi(this))}}\n}''','''class MainActivity:ComponentActivity(){\n    override fun onCreate(savedInstanceState:Bundle?){\n        super.onCreate(savedInstanceState)\n        window.setFlags(WindowManager.LayoutParams.FLAG_SECURE,WindowManager.LayoutParams.FLAG_SECURE)\n        setContent{ManagementApp(ManagementApi(this))}\n    }\n}''')
s=s.replace('''safe("partner_documents","id,partner_id,document_type,status,rejection_reason,created_at,is_current"''','''safe("partner_documents","id,partner_id,document_type,status,rejection_reason,created_at,is_current,storage_path,mime_type"''')

old='''@Composable private fun DocumentReviewRow(api:ManagementApi,d:JSONObject,enabled:Boolean,onChanged:()->Unit){\n    val scope=rememberCoroutineScope();var busy by remember{mutableStateOf(false)};var msg by remember{mutableStateOf("")};var action by remember{mutableStateOf<String?>(null)};var reason by remember{mutableStateOf("")}\n    val status=d.optString("status","-");val reviewable=status in setOf("SUBMITTED","IN_REVIEW","REQUIRES_UPDATE")\n    Surface(shape=RoundedCornerShape(14.dp),color=Soft,modifier=Modifier.fillMaxWidth()){\n        Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){\n            Text(d.optString("document_type","Dokumen"),fontWeight=FontWeight.Medium)\n            Text(status,style=MaterialTheme.typography.bodySmall,color=Color.Gray)\n            if(enabled&&reviewable) Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){\n                Button(onClick={action="VERIFIED"},enabled=!busy){Text("Verifikasi")}\n                OutlinedButton(onClick={action="REJECTED"},enabled=!busy){Text("Tolak")}\n            }\n            if(msg.isNotBlank()) Text(msg,style=MaterialTheme.typography.bodySmall,color=if(msg.startsWith("Gagal"))MaterialTheme.colorScheme.error else Green)\n        }\n    }\n    if(action!=null) AlertDialog(onDismissRequest={if(!busy)action=null},title={Text(if(action=="VERIFIED")"Verifikasi dokumen?" else "Tolak dokumen?")},text={Column{Text("Keputusan dicatat server dan tunduk pada permission partner.verify.");if(action=="REJECTED")OutlinedTextField(reason,{reason=it},label={Text("Alasan penolakan")},modifier=Modifier.fillMaxWidth().padding(top=10.dp))}},confirmButton={Button(onClick={scope.launch{busy=true;try{api.rpc("review_partner_document",JSONObject().put("p_document_id",d.optString("id")).put("p_decision",action).put("p_reason",if(reason.isBlank())JSONObject.NULL else reason));msg="Berhasil: ${action}";action=null;reason="";onChanged()}catch(e:Exception){msg="Gagal: ${e.message}";action=null}finally{busy=false}}},enabled=!busy&&(action!="REJECTED"||reason.isNotBlank())){Text("Konfirmasi")}},dismissButton={TextButton(onClick={action=null},enabled=!busy){Text("Batal")}})\n}\n'''
new='''@Composable private fun DocumentReviewRow(api:ManagementApi,d:JSONObject,enabled:Boolean,onChanged:()->Unit){\n    val context=LocalContext.current\n    val scope=rememberCoroutineScope();var busy by remember{mutableStateOf(false)};var msg by remember{mutableStateOf("")};var action by remember{mutableStateOf<String?>(null)};var reason by remember{mutableStateOf("")}\n    val status=d.optString("status","-");val reviewable=status in setOf("SUBMITTED","IN_REVIEW","REQUIRES_UPDATE")\n    val storagePath=d.optString("storage_path").trim();val mime=d.optString("mime_type").ifBlank{"application/octet-stream"}\n    Surface(shape=RoundedCornerShape(14.dp),color=Soft,modifier=Modifier.fillMaxWidth()){\n        Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){\n            Text(d.optString("document_type","Dokumen"),fontWeight=FontWeight.Medium)\n            Text(status,style=MaterialTheme.typography.bodySmall,color=Color.Gray)\n            if(storagePath.isNotBlank()) Text("Bukti private tersedia",style=MaterialTheme.typography.bodySmall,color=Green)\n            if(enabled && storagePath.isNotBlank()) OutlinedButton(onClick={scope.launch{busy=true;msg="";try{\n                val bytes=api.downloadStorage("partner-kyc-private",storagePath)\n                val ext=when{mime.contains("pdf",true)->"pdf";mime.contains("png",true)->"png";mime.contains("webp",true)->"webp";else->"jpg"}\n                val file=withContext(Dispatchers.IO){\n                    val dir=File(context.cacheDir,"kyc-review").apply{mkdirs()}\n                    dir.listFiles()?.forEach{it.delete()}\n                    File(dir,"${d.optString("id","evidence").replace(Regex("[^A-Za-z0-9_-]"),"_")}.$ext").apply{writeBytes(bytes)}\n                }\n                val uri=FileProvider.getUriForFile(context,"${context.packageName}.fileprovider",file)\n                context.startActivity(Intent(Intent.ACTION_VIEW).setDataAndType(uri,mime).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION))\n                msg="Bukti dibuka dari storage private"\n            }catch(e:Exception){msg="Gagal membuka bukti: ${e.message}"}finally{busy=false}}},enabled=!busy){Icon(Icons.Default.Visibility,null);Spacer(Modifier.width(6.dp));Text("Lihat Bukti") }\n            if(enabled&&reviewable) Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){\n                Button(onClick={action="VERIFIED"},enabled=!busy){Text("Verifikasi")}\n                OutlinedButton(onClick={action="REJECTED"},enabled=!busy){Text("Tolak")}\n            }\n            if(enabled && storagePath.isBlank()) Text("Storage path belum tersedia pada row ini; reviewer tidak boleh memverifikasi tanpa meninjau bukti.",style=MaterialTheme.typography.bodySmall,color=Color(0xFF9A3412))\n            if(msg.isNotBlank()) Text(msg,style=MaterialTheme.typography.bodySmall,color=if(msg.startsWith("Gagal"))MaterialTheme.colorScheme.error else Green)\n        }\n    }\n    if(action!=null) AlertDialog(onDismissRequest={if(!busy)action=null},title={Text(if(action=="VERIFIED")"Verifikasi dokumen?" else "Tolak dokumen?")},text={Column{Text("Keputusan dicatat server dan tunduk pada permission partner.verify.");if(storagePath.isBlank())Text("Peringatan: bukti private belum dapat dibuka pada row ini.",color=Color(0xFF9A3412));if(action=="REJECTED")OutlinedTextField(reason,{reason=it},label={Text("Alasan penolakan")},modifier=Modifier.fillMaxWidth().padding(top=10.dp))}},confirmButton={Button(onClick={scope.launch{busy=true;try{api.rpc("review_partner_document",JSONObject().put("p_document_id",d.optString("id")).put("p_decision",action).put("p_reason",if(reason.isBlank())JSONObject.NULL else reason));msg="Berhasil: ${action}";action=null;reason="";onChanged()}catch(e:Exception){msg="Gagal: ${e.message}";action=null}finally{busy=false}}},enabled=!busy&&storagePath.isNotBlank()&&(action!="REJECTED"||reason.isNotBlank())){Text("Konfirmasi")}},dismissButton={TextButton(onClick={action=null},enabled=!busy){Text("Batal")}})\n}\n'''
if old not in s: raise SystemExit("document review block missing")
s=s.replace(old,new,1)
p.write_text(s)

# README
p=root/"README.md"
s=p.read_text()
s=s.replace('Version code: 3','Version code: 4')
s=s.replace('0.2.1-pilot-m1.1','0.2.2-pilot-m1.2')
s += '''\n\n## M1.2 — Private KYC Evidence Review\n\n- Reviewer can preview `partner-kyc-private` evidence using the signed-in Management access token.\n- No public URL and no service-role secret are used; Storage RLS remains authoritative.\n- Evidence is stored only in app-private cache and exposed temporarily through non-exported `FileProvider`.\n- `FLAG_SECURE` protects Management screens against screenshots/screen recording on supported Android devices.\n- Verify/Reject confirmation is disabled when the row has no `storage_path`, preventing blind verification.\n- Application approval and mutable Pilot Control remain locked until their server contracts are verified.\n'''
p.write_text(s)

print("M1.2 KYC evidence review hardening applied")
